1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvCriticalItem,
14	  TvDateRange,
15	  TvException,
16	  TvExceptionsResult,
17	  TvFreshness,
18	  TvFreshnessLevel,
19	  TvPeriod,
20	  TvRagStatus,
21	  TvRecentMove,
22	  TvStockAlertItem,
23	  TvWeekSegment,
24	  TvWeeklyGoal,
25	} from './types';
26	
27	// ─────────────────────────────────────────────────────────────────────────────
28	// Constantes de negócio
29	// ─────────────────────────────────────────────────────────────────────────────
30	
31	/**
32	 * Janela de funcionamento das LOJAS usada no pró-rata da meta (hora local,
33	 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
34	 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
35	 */
36	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 10, end: 22 };
37	
38	/**
39	 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
40	 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
41	 */
42	export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };
43	
44	/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
45	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
46	
47	/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
48	export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;
49	
50	/**
51	 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
52	 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
53	 */
54	export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;
55	
56	/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
57	export const LIVE_SALES_AMBER_FROM_HOUR = 11;
58	
59	/** Máximo de linhas exibidas na faixa de exceções. */
60	export const TV_EXCEPTIONS_LIMIT = 7;
61	
62	/** Itens do mini-feed "AGORA" por coluna de unidade. */
63	export const TV_MINI_FEED_SIZE = 3;
64	
65	/** Itens de estoque crítico exibidos na coluna (lista completa no drill-down). */
66	export const TV_CRITICAL_TOP_N = 5;
67	
68	/** Máximo de linhas do feed de movimentações no drill-down por loja. */
69	export const TV_DETAIL_FEED_LIMIT = 50;
70	
71	/**
72	 * Setor canônico de `produtos_master.setor` cujos itens entram nos ALERTAS
73	 * de estoque crítico do painel (regra do CTO 2026-06-05: alertas só do setor
74	 * de produtos vendáveis — EMBALAGENS, INSUMOS, CÂMARA FRIA, ITENS COZINHA,
75	 * MERCEARIA, COMIDAS, PRODUTOS DE LIMPEZA etc. ficam FORA).
76	 *
77	 * Comparar SEMPRE por igualdade exata pós-{@link normalizeSetor} (nunca por
78	 * prefixo/ILIKE: existe o setor "PRODUTOS DE LIMPEZA") — use
79	 * {@link isTvAlertSetor}.
80	 */
81	export const TV_ALERT_SETOR = 'PRODUTOS';
82	
83	/**
84	 * ÚNICA loja cujo faturamento de PDV embute delivery (BSB Shopping): lá o
85	 * iFood/delivery passa pelo caixa Degust junto com o balcão, então o card
86	 * quebra "Loja × Delivery" (R1 da spec tv-acompanhamento-live). Nas demais
87	 * lojas o delivery NÃO entra no PDV — quebra não se aplica.
88	 *
89	 * É `lojas.id` interno (não código Degust). Constante nomeada de propósito:
90	 * exceção de NEGÓCIO documentada, não um hardcode espalhado.
91	 */
92	export const TV_DELIVERY_SPLIT_LOJA_ID = 6;
93	
94	// ─────────────────────────────────────────────────────────────────────────────
95	// Datas (helpers locais, sem dependência de timezone UTC)
96	// ─────────────────────────────────────────────────────────────────────────────
97	
98	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
99	export function toIsoDateLocal(d: Date): string {
100	  const y = d.getFullYear();
101	  const m = String(d.getMonth() + 1).padStart(2, '0');
102	  const day = String(d.getDate()).padStart(2, '0');
103	  return `${y}-${m}-${day}`;
104	}
105	
106	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
107	export function parseIsoDateLocal(iso: string): Date {
108	  const [y, m, d] = iso.split('-').map(Number);
109	  return new Date(y, (m ?? 1) - 1, d ?? 1);
110	}
111	
112	/** Soma `days` dias a uma data, retornando nova instância. */
113	export function addDays(d: Date, days: number): Date {
114	  const out = new Date(d);
115	  out.setDate(out.getDate() + days);
116	  return out;
117	}
118	
119	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
120	export function formatLaggedDateLabel(isoDate: string): string {
121	  const d = parseIsoDateLocal(isoDate);
122	  const dd = String(d.getDate()).padStart(2, '0');
123	  const mm = String(d.getMonth() + 1).padStart(2, '0');
124	  return `até ${dd}/${mm}`;
125	}
126	
127	/**
128	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
129	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
130	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
131	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
132	 */
133	export function parseBrDateTime(value: string | null | undefined): Date | null {
134	  if (!value) return null;
135	  const m = value.match(
136	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
137	  );
138	  if (m) {
139	    const [, dd, mm, yyyy, hh, mi, ss] = m;
140	    const month = Number(mm);
141	    const day = Number(dd);
142	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
143	    return new Date(
144	      Number(yyyy),
145	      month - 1,
146	      day,
147	      Number(hh),
148	      Number(mi),
149	      ss ? Number(ss) : 0,
150	    );
151	  }
152	  const fallback = new Date(value);
153	  return Number.isNaN(fallback.getTime()) ? null : fallback;
154	}
155	
156	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
157	export function timeHHMMFromIso(iso: string | null | undefined): string {
158	  if (!iso) return '—';
159	  const d = new Date(iso);
160	  if (Number.isNaN(d.getTime())) return '—';
161	  const hh = String(d.getHours()).padStart(2, '0');
162	  const mm = String(d.getMinutes()).padStart(2, '0');
163	  return `${hh}:${mm}`;
164	}
165	
166	// ─────────────────────────────────────────────────────────────────────────────
167	// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
168	// ─────────────────────────────────────────────────────────────────────────────
169	
170	/**
171	 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
172	 * - `today`: hoje → hoje;
173	 * - `week`: segunda-feira da semana corrente → hoje;
174	 * - `month`: dia 1º do mês corrente → hoje.
175	 */
176	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
177	  const today = toIsoDateLocal(now);
178	  if (period === 'today') return { from: today, to: today };
179	  if (period === 'week') {
180	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
181	    const dowFromMonday = (now.getDay() + 6) % 7;
182	    const monday = addDays(now, -dowFromMonday);
183	    return { from: toIsoDateLocal(monday), to: today };
184	  }
185	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
186	  return { from: toIsoDateLocal(firstOfMonth), to: today };
187	}
188	
189	/**
190	 * Período ANTERIOR equivalente para comparativos do filtro global:
191	 * - `today`: ontem → ontem;
192	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
193	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
194	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
195	 */
196	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
197	  if (period === 'today') {
198	    const yesterday = toIsoDateLocal(addDays(now, -1));
199	    return { from: yesterday, to: yesterday };
200	  }
201	  if (period === 'week') {
202	    const dowFromMonday = (now.getDay() + 6) % 7;
203	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
204	    return {
205	      from: toIsoDateLocal(mondayLastWeek),
206	      to: toIsoDateLocal(addDays(now, -7)),
207	    };
208	  }
209	  const y = now.getFullYear();
210	  const m = now.getMonth();
211	  const firstPrev = new Date(y, m - 1, 1);
212	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
213	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
214	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
215	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
216	}
217	
218	/**
219	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
220	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
221	 */
222	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
223	  const from = parseIsoDateLocal(range.from);
224	  const to = parseIsoDateLocal(range.to);
225	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
226	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
227	  return {
228	    from: toIsoDateLocal(addDays(from, -days)),
229	    to: toIsoDateLocal(addDays(to, -days)),
230	  };
231	}
232	
233	/**
234	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
235	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
236	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
237	 * (exclusivo — usar `.lt`, nunca `.lte`).
238	 */
239	export function rangeToLocalDayBounds(range: TvDateRange): {
240	  startIso: string;
241	  endExclusiveIso: string;
242	} {
243	  const start = parseIsoDateLocal(range.from);
244	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
245	  return {
246	    startIso: start.toISOString(),
247	    endExclusiveIso: endExclusive.toISOString(),
248	  };
249	}
250	
251	/**
252	 * Range do filtro global DESLOCADO `offset` períodos no tempo (R2 —
253	 * histórico navegável). Offset 0 = comportamento de {@link periodRange}
254	 * (período corrente, parcial até hoje). Offset −n = período PASSADO
255	 * COMPLETO n posições atrás:
256	 * - `today`: o dia inteiro n dias atrás;
257	 * - `week`: a semana seg-dom COMPLETA n semanas atrás;
258	 * - `month`: o mês-calendário COMPLETO n meses atrás.
259	 *
260	 * Offset positivo não é suportado (não há futuro a navegar) — tratado
261	 * como 0 por segurança.
262	 */
263	export function shiftedPeriodRange(
264	  period: TvPeriod,
265	  offset: number,
266	  now: Date,
267	): TvDateRange {
268	  if (offset >= 0) return periodRange(period, now);
269	  if (period === 'today') {
270	    const day = toIsoDateLocal(addDays(now, offset));
271	    return { from: day, to: day };
272	  }
273	  if (period === 'week') {
274	    const dowFromMonday = (now.getDay() + 6) % 7;
275	    const monday = addDays(now, -dowFromMonday + offset * 7);
276	    return { from: toIsoDateLocal(monday), to: toIsoDateLocal(addDays(monday, 6)) };
277	  }
278	  const first = new Date(now.getFullYear(), now.getMonth() + offset, 1);
279	  // `new Date(y, m+1, 0)` = último dia do mês `m`
280	  const last = new Date(now.getFullYear(), now.getMonth() + offset + 1, 0);
281	  return { from: toIsoDateLocal(first), to: toIsoDateLocal(last) };
282	}
283	
284	// ─────────────────────────────────────────────────────────────────────────────
285	// Meta mensal — semanas seg-dom recortadas ao mês + redistribuição (R4)
286	// ─────────────────────────────────────────────────────────────────────────────
287	
288	/**
289	 * Segmentos seg-dom de um mês, RECORTADOS aos limites do mês: o primeiro
290	 * e o último podem ter menos de 7 dias (mês que começa/termina no meio da
291	 * semana). `index` é 1-based ("Semana 1").
292	 *
293	 * @param year - Ano (ex.: 2026).
294	 * @param monthIndex0 - Mês 0-based (convenção JS `Date.getMonth()`).
295	 */
296	export function monthWeekSegments(
297	  year: number,
298	  monthIndex0: number,
299	): TvWeekSegment[] {
300	  const lastDay = new Date(year, monthIndex0 + 1, 0).getDate();
301	  const segments: TvWeekSegment[] = [];
302	  let day = 1;
303	  let index = 1;
304	  while (day <= lastDay) {
305	    const start = new Date(year, monthIndex0, day);
306	    const dowFromMonday = (start.getDay() + 6) % 7;
307	    const endDay = Math.min(day + (6 - dowFromMonday), lastDay);
308	    segments.push({
309	      index,
310	      from: toIsoDateLocal(start),
311	      to: toIsoDateLocal(new Date(year, monthIndex0, endDay)),
312	      days: endDay - day + 1,
313	    });
314	    day = endDay + 1;
315	    index += 1;
316	  }
317	  return segments;
318	}
319	
320	/**
321	 * Metas semanais do mês de `now` com REDISTRIBUIÇÃO iterativa da meta
322	 * mensal (que é fixa): para cada segmento, em ordem,
323	 * `target = (metaMensal − comprometido) × dias do segmento ÷ dias restantes`,
324	 * onde "comprometido" acumula o REALIZADO das semanas já encerradas e o
325	 * TARGET das semanas correntes/futuras (assume on-target dali em diante).
326	 *
327	 * Consequências (A4 da spec):
328	 * - semana que não bate a meta ⇒ targets das seguintes SOBEM;
329	 * - semana que supera ⇒ targets das seguintes DESCEM;
330	 * - invariante: realizado das semanas passadas + soma dos targets
331	 *   restantes = metaMensal, sempre (targets podem ficar negativos se o
332	 *   realizado já passou da meta — honesto, sem clamp).
333	 *
334	 * `achieved` = soma de `realizadoPorDia` nos dias do segmento (semanas
335	 * passadas e corrente); null para semanas futuras (sem dados ainda).
336	 */
337	export function weeklyTargets(
338	  metaMensal: number,
339	  realizadoPorDia: Map<string, number>,
340	  now: Date,
341	): TvWeeklyGoal[] {
342	  const segments = monthWeekSegments(now.getFullYear(), now.getMonth());
343	  const todayIso = toIsoDateLocal(now);
344	  const sumSegment = (seg: TvWeekSegment): number => {
345	    let sum = 0;
346	    let d = parseIsoDateLocal(seg.from);
347	    for (let i = 0; i < seg.days; i += 1) {
348	      sum += realizadoPorDia.get(toIsoDateLocal(d)) ?? 0;
349	      d = addDays(d, 1);
350	    }
351	    return sum;
352	  };
353	
354	  let committed = 0;
355	  let daysRemaining = segments.reduce((s, seg) => s + seg.days, 0);
356	  const out: TvWeeklyGoal[] = [];
357	  for (const seg of segments) {
358	    const target =
359	      daysRemaining > 0 ? ((metaMensal - committed) * seg.days) / daysRemaining : 0;
360	    const isPast = seg.to < todayIso;
361	    const isCurrent = seg.from <= todayIso && todayIso <= seg.to;
362	    const achieved = isPast || isCurrent ? sumSegment(seg) : null;
363	    out.push({ segment: seg, target, achieved, isCurrent });
364	    // Passadas comprometem o REAL (déficit/superávit redistribui);
365	    // corrente/futuras comprometem o TARGET (projeção on-target).
366	    committed += isPast ? (achieved ?? 0) : target;
367	    daysRemaining -= seg.days;
368	  }
369	  return out;
370	}
371	
372	// ─────────────────────────────────────────────────────────────────────────────
373	// Curva horária (R5) + projeção de fim de mês (R3)
374	// ─────────────────────────────────────────────────────────────────────────────
375	
376	/**
377	 * Base "ontem até a MESMA hora" usando a curva horária REAL do dia de
378	 * referência: `prevDayTotal` × fração, onde fração = cumulativo de
379	 * `prevDayByHour` até HH:mm ÷ cumulativo total. A hora corrente entra com
380	 * fração linear do minuto dentro da hora (15:30 → metade do bucket "15").
381	 *
382	 * A curva é usada APENAS como fração (kits têm valorUnitario 0 na fonte) —
383	 * o valor absoluto vem sempre do total oficial `prevDayTotal`.
384	 *
385	 * Retorna null quando não há base honesta — curva ausente/vazia, cumulativo
386	 * total 0, total não positivo ou fração 0 (antes da 1ª venda do dia de
387	 * referência) — para o caller cair no fallback pró-rata linear existente.
388	 */
389	export function hourlyPaceBase(
390	  prevDayTotal: number,
391	  prevDayByHour: Record<string, number> | undefined,
392	  now: Date,
393	): number | null {
394	  if (prevDayTotal <= 0 || !prevDayByHour) return null;
395	  const buckets: Array<[number, number]> = [];
396	  for (const [hh, value] of Object.entries(prevDayByHour)) {
397	    const hour = Number(hh);
398	    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue;
399	    buckets.push([hour, value]);
400	  }
401	  const cumTotal = buckets.reduce((s, [, v]) => s + v, 0);
402	  if (cumTotal <= 0) return null;
403	  const currentHour = now.getHours();
404	  const minuteFraction = (now.getMinutes() + now.getSeconds() / 60) / 60;
405	  let cumNow = 0;
406	  for (const [hour, value] of buckets) {
407	    if (hour < currentHour) cumNow += value;
408	    else if (hour === currentHour) cumNow += value * minuteFraction;
409	  }
410	  if (cumNow <= 0) return null;
411	  return prevDayTotal * (cumNow / cumTotal);
412	}
413	
414	/**
415	 * Projeção de fim de mês por run-rate (mtd ÷ dias decorridos × dias do
416	 * mês), com "dias decorridos" = dias COMPLETOS decorridos + 1 (hoje conta
417	 * inteiro — sem fração de dia, decisão da spec). No dia 1º a projeção é
418	 * o run-rate de 1 dia (`mtd × diasDoMês`).
419	 */
420	export function monthEndProjection(mtdTotal: number, now: Date): number {
421	  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
422	  const daysElapsed = now.getDate();
423	  return (mtdTotal / daysElapsed) * daysInMonth;
424	}
425	
426	// ─────────────────────────────────────────────────────────────────────────────
427	// Pró-rata da meta
428	// ─────────────────────────────────────────────────────────────────────────────
429	
430	/**
431	 * Fração linear do dia comercial já decorrida em `now`.
432	 *
433	 * - Antes da abertura → 0 (não há venda esperada ainda).
434	 * - Depois do fechamento → 1 (meta integral esperada).
435	 * - Dentro da janela → interpolação linear simples (pró-rata).
436	 */
437	export function businessDayFraction(
438	  now: Date,
439	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
440	): number {
441	  const { start, end } = hours;
442	  if (end <= start) {
443	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
444	    return now.getHours() >= end ? 1 : 0;
445	  }
446	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
447	  if (h <= start) return 0;
448	  if (h >= end) return 1;
449	  return (h - start) / (end - start);
450	}
451	
452	/**
453	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
454	 *
455	 * Retorna null quando não dá para calcular com honestidade:
456	 * - meta ausente/zerada (sem referência), ou
457	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
458	 */
459	export function pctOfProRataTarget(
460	  sold: number,
461	  dailyTarget: number | null | undefined,
462	  now: Date,
463	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
464	): number | null {
465	  if (dailyTarget == null || dailyTarget <= 0) return null;
466	  const fraction = businessDayFraction(now, hours);
467	  if (fraction <= 0) return null;
468	  return (sold / (dailyTarget * fraction)) * 100;
469	}
470	
471	/**
472	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
473	 * cujo dia de referência já encerrou.
474	 */
475	export function pctOfFullDayTarget(
476	  sold: number,
477	  dailyTarget: number | null | undefined,
478	): number | null {
479	  if (dailyTarget == null || dailyTarget <= 0) return null;
480	  return (sold / dailyTarget) * 100;
481	}
482	
483	// ─────────────────────────────────────────────────────────────────────────────
484	// Deltas comparativos (genéricos: vendas, perdas, compras — qualquer base)
485	// ─────────────────────────────────────────────────────────────────────────────
486	
487	/**
488	 * Delta % de `current` vs uma base de referência qualquer (ontem, semana
489	 * passada, período anterior do filtro…). Retorna null quando a base é
490	 * ausente ou não positiva — sem base honesta, sem número inventado.
491	 */
492	export function relativeDelta(
493	  current: number,
494	  base: number | null | undefined,
495	): number | null {
496	  if (base == null || base <= 0) return null;
497	  return ((current - base) / base) * 100;
498	}
499	
500	/**
501	 * Delta % vs MESMO DIA da semana anterior — caso particular de
502	 * {@link relativeDelta}, mantido pelo nome de domínio (comparativo
503	 * SECUNDÁRIO desde a v3; o principal é vs dia anterior).
504	 */
505	export function weekOverWeekDelta(
506	  current: number,
507	  lastWeek: number | null | undefined,
508	): number | null {
509	  return relativeDelta(current, lastWeek);
510	}
511	
512	/**
513	 * Base PRÓ-RATEADA de QUALQUER dia de referência para deltas do canal LIVE:
514	 * `referenceDayTotal × businessDayFraction(now)` — o delta resultante compara
515	 * hoje (dia parcial) vs o MESMO PONTO do dia de referência (ontem, semana
516	 * passada…), assumindo distribuição intra-dia linear na janela (mesma fração
517	 * usada no pró-rata da meta, por consistência).
518	 *
519	 * Comparar dia parcial com dia completo inflava a queda de manhã.
520	 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
521	 *
522	 * Retorna null quando a base é ausente/não positiva ou antes da abertura
523	 * (fração 0 — não há ponto de comparação honesto).
524	 */
525	export function proRataDayBase(
526	  referenceDayTotal: number | null | undefined,
527	  now: Date,
528	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
529	): number | null {
530	  if (referenceDayTotal == null || referenceDayTotal <= 0) return null;
531	  const fraction = businessDayFraction(now, hours);
532	  if (fraction <= 0) return null;
533	  return referenceDayTotal * fraction;
534	}
535	
536	/**
537	 * Alias histórico de {@link proRataDayBase} com o dia de referência fixado
538	 * em "mesmo dia da semana passada" (nome da v1/v2 — mantido para não quebrar
539	 * a API existente).
540	 */
541	export function proRataLastWeekBase(
542	  lastWeek: number | null | undefined,
543	  now: Date,
544	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
545	): number | null {
546	  return proRataDayBase(lastWeek, now, hours);
547	}
