553	/** Entrada da classificação RAG de uma unidade. */
554	export interface StoreRagInput {
555	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
556	  stockOutCount: number;
557	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
558	  stockLowCount: number;
559	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
560	  pctMetaProRata: number | null;
561	  /** true quando a unidade tem venda ao vivo (canal Degust). */
562	  isLiveChannel: boolean;
563	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
564	  lastMovementAt: Date | string | null;
565	  /** Instante da avaliação. */
566	  now: Date;
567	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
568	  hours?: TvBusinessHours;
569	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
570	  noMovementThresholdHours?: number;
571	}
572	
573	/**
574	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
575	 *
576	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
577	 *   não faz sentido alertar madrugada sem bipagem.
578	 * - A referência é clampada ao início da janela de hoje: se a última
579	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
580	 */
581	export function hoursWithoutMovementInWindow(
582	  lastMovementAt: Date | string | null,
583	  now: Date,
584	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
585	): number | null {
586	  const fraction = businessDayFraction(now, hours);
587	  if (fraction <= 0 || fraction >= 1) return null;
588	  const windowStart = new Date(now);
589	  windowStart.setHours(hours.start, 0, 0, 0);
590	  const last = lastMovementAt
591	    ? new Date(lastMovementAt).getTime()
592	    : Number.NEGATIVE_INFINITY;
593	  const ref = Math.max(last, windowStart.getTime());
594	  return (now.getTime() - ref) / 3_600_000;
595	}
596	
597	/**
598	 * Classificação RAG de uma unidade (management-by-exception).
599	 *
600	 * Regras (design.md §1.6, ordem de precedência):
601	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
602	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
603	 *   manhã, quando o pró-rata ainda é instável).
604	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
605	 *   movimentação há mais que o threshold dentro da janela OU venda live com
606	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
607	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
608	 *   em canal live e com meta cadastrada (pct != null).
609	 * - OK: nenhum desvio — tela calma, sem cor.
610	 */
611	export function classifyStoreRag(input: StoreRagInput): {
612	  status: TvRagStatus;
613	  reasons: string[];
614	} {
615	  const hours = input.hours ?? TV_BUSINESS_HOURS;
616	  const noMovementThreshold =
617	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
618	  const reasons: string[] = [];
619	
620	  // ── Vermelho: só ruptura (item zerado em alerta) ──
621	  if (input.stockOutCount > 0) {
622	    reasons.push(
623	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
624	    );
625	    return { status: 'red', reasons };
626	  }
627	
628	  // ── Âmbar ──
629	  if (input.stockLowCount > 0) {
630	    reasons.push(
631	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
632	    );
633	  }
634	  const gapHours = hoursWithoutMovementInWindow(
635	    input.lastMovementAt,
636	    input.now,
637	    hours,
638	  );
639	  if (gapHours !== null && gapHours > noMovementThreshold) {
640	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
641	  }
642	  if (
643	    input.isLiveChannel &&
644	    input.pctMetaProRata !== null &&
645	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
646	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
647	  ) {
648	    reasons.push(
649	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
650	    );
651	  }
652	  if (reasons.length > 0) return { status: 'amber', reasons };
653	
654	  return { status: 'ok', reasons: [] };
655	}
