670	/**
671	 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
672	 * da última bipagem + janela), nunca por parsing de string de ragReasons —
673	 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
674	 * cobre também a fábrica (janela/threshold próprios via parâmetros).
675	 * Retorna null quando não há gap acima do threshold dentro da janela.
676	 */
677	export function buildNoMovementException(
678	  input: NoMovementExceptionInput,
679	): TvException | null {
680	  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
681	  const gap = hoursWithoutMovementInWindow(
682	    input.lastMovementAt,
683	    input.now,
684	    input.hours ?? TV_BUSINESS_HOURS,
685	  );
686	  if (gap === null || gap <= threshold) return null;
687	  return {
688	    id: `no-movement:${input.lojaId}`,
689	    kind: 'no-movement',
690	    severity: 'amber',
691	    lojaId: input.lojaId,
692	    lojaNome: input.lojaNome,
693	    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
694	  };
695	}
