697	// ─────────────────────────────────────────────────────────────────────────────
698	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
699	// ─────────────────────────────────────────────────────────────────────────────
700	
701	function trimOneDecimal(v: number): string {
702	  const rounded = Math.round(v * 10) / 10;
703	  return rounded.toLocaleString('pt-BR', {
704	    minimumFractionDigits: 0,
705	    maximumFractionDigits: 1,
706	  });
707	}
708	
709	/**
710	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
711	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
712	 * Valores negativos preservam o sinal ("-R$ 1,2k").
713	 */
714	export function formatCompactBRL(value: number): string {
715	  const sign = value < 0 ? '-' : '';
716	  const abs = Math.abs(value);
717	  // Bump pra M quando o arredondamento em k chegaria a 1000k
718	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
719	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
720	  }
721	  if (abs >= 1_000) {
722	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
723	  }
724	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
725	}
