826	/** Linha mínima de `movimentacoes` necessária à agregação. */
827	export interface MovementRow {
828	  loja_id: number | null;
829	  tipo_movimentacao: string;
830	  data_movimentacao: string | null;
831	}
832	
833	/** Resultado por loja da agregação de movimentações do dia. */
834	export interface MovementAggregate {
835	  entradas: number;
836	  saidas: number;
837	  ultimaBipagem: string | null;
838	}
839	
840	/**
841	 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
842	 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
843	 * são ignoradas.
844	 */
845	export function aggregateMovements(
846	  rows: MovementRow[],
847	): Map<number, MovementAggregate> {
848	  const out = new Map<number, MovementAggregate>();
849	  for (const row of rows) {
850	    if (row.loja_id == null) continue;
851	    let agg = out.get(row.loja_id);
852	    if (!agg) {
853	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
854	      out.set(row.loja_id, agg);
855	    }
856	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
857	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
858	    if (
859	      row.data_movimentacao &&
860	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
861	    ) {
862	      agg.ultimaBipagem = row.data_movimentacao;
863	    }
864	  }
865	  return out;
866	}
