890	/** Linha mínima de `estoque` (com nome do produto ativo já joinado). */
891	export interface StockRow {
892	  loja_id: number | null;
893	  quantidade_atual: number | null;
894	  quantidade_minima: number | null;
895	  produtoNome: string;
896	  /** `produtos_master.setor` cru (caixa/acentos inconsistentes no banco). */
897	  setor: string | null;
898	}
