944	/**
945	 * Constrói as exceções de estoque (item × loja) a partir do detalhe por loja.
946	 * Itens zerados viram exceção vermelha; abaixo do mínimo, âmbar.
947	 */
948	export function buildStockExceptions(
949	  detailByLoja: Map<number, StockDetail>,
950	  lojaNomeById: Map<number, string>,
951	): TvException[] {
952	  const out: TvException[] = [];
953	  for (const [lojaId, detail] of detailByLoja) {
954	    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
955	    for (const item of detail.itens) {
956	      out.push({
957	        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
958	        kind: item.zerado ? 'stock-out' : 'stock-low',
959	        severity: item.zerado ? 'red' : 'amber',
960	        lojaId,
961	        lojaNome,
962	        message: item.zerado
963	          ? `${item.produtoNome} zerado — ${lojaNome}`
964	          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
965	        produtoNome: item.produtoNome,
966	        quantidade: item.quantidade,
967	        quantidadeMinima: item.quantidadeMinima,
968	      });
969	    }
970	  }
971	  return out;
972	}
