974	/** Linha de venda live normalizada (resposta da edge `degust-pos-financial`). */
975	export interface FlashRow {
976	  loja_id: number;
977	  nome_loja: string;
978	  total_vendas: number;
979	  total_cupons: number;
980	  ticket_medio: number;
981	  caixa_aberto: boolean;
