31	/** Modal do relatório diário do Painel TV (copiar/compartilhar). */
32	export function TvReportModal({ open, onOpenChange }: TvReportModalProps) {
33	  // Dia-base default/máximo = ontem (relatório matinal fala do dia fechado)
