57	      'noopener,noreferrer',
58	    );
59	  };
60	
61	  return (
62	    <Dialog open={open} onOpenChange={onOpenChange}>
63	      <DialogContent
64	        className="max-w-lg border-white/40 bg-white/80 backdrop-blur-xl dark:border-white/10 dark:bg-black/60 sm:rounded-2xl"
