48	interface MetasLoja {
49	  id: number;
50	  nome: string;
51	}
52	
53	interface MetaRow {
54	  loja_id: number;
55	  dia_semana: number;
56	  valor_meta: number;
57	}
58	
59	function cellKey(lojaId: number, dia: number): string {
60	  return `${lojaId}:${dia}`;
61	}
62	
63	function isFactoryTipo(tipo: string | null): boolean {
64	  const t = (tipo ?? '').toLowerCase();
65	  return t.startsWith('fabrica') || t.startsWith('fábrica');
66	}
67	
68	async function fetchLojasVenda(): Promise<MetasLoja[]> {
69	  const { data, error } = await supabase
70	    .from('lojas')
71	    .select('id, nome, tipo')
72	    .eq('ativo', true)
73	    .order('id');
74	  if (error) throw error;
75	  return (data ?? [])
76	    .filter((l) => !isFactoryTipo(l.tipo))
77	    .map((l) => ({ id: l.id, nome: l.nome }));
78	}
79	
80	async function fetchMetas(): Promise<MetaRow[]> {
81	  const { data, error } = await supabase
82	    .from('metas_vendas')
83	    .select('loja_id, dia_semana, valor_meta')
84	    .limit(1000);
85	  if (error) throw error;
86	  return data ?? [];
87	}
88	
89	/** Linha de `metas_mensais` de um mês (loja_id NULL = meta da rede). */
90	interface MetaMensalRow {
91	  id: string;
92	  loja_id: number | null;
93	  valor_meta: number;
94	}
95	
96	async function fetchMetasMensais(ano: number, mes: number): Promise<MetaMensalRow[]> {
97	  const { data, error } = await supabase
98	    .from('metas_mensais')
99	    .select('id, loja_id, valor_meta')
100	    .eq('ano', ano)
101	    .eq('mes', mes);
102	  if (error) throw error;
103	  return data ?? [];
104	}
105	
106	/** Parse de input de meta: vazio/inválido → null; aceita vírgula decimal. */
107	function parseMetaInput(raw: string): number | null {
108	  if (raw.trim() === '') return null;
109	  const parsed = Number(raw.replace(',', '.'));
110	  if (!Number.isFinite(parsed) || parsed < 0) return null;
111	  return parsed;
112	}
