114	/** Grade de metas do Painel TV (admin only — rota protegida em App.tsx). */
115	export default function TvMetasPage() {
116	  const navigate = useNavigate();
117	  const queryClient = useQueryClient();
118	
119	  const lojasQuery = useQuery({ queryKey: ['tv-metas', 'lojas'], queryFn: fetchLojasVenda });
120	  const metasQuery = useQuery({ queryKey: ['tv-metas', 'valores'], queryFn: fetchMetas });
121	
122	  // ── Meta mensal (R4): mês/ano selecionável, rede + por loja ──
123	  const [mensalAno, setMensalAno] = useState(() => new Date().getFullYear());
124	  const [mensalMes, setMensalMes] = useState(() => new Date().getMonth() + 1);
125	  const [showMetasPorLoja, setShowMetasPorLoja] = useState(false);
126	  const mensaisQuery = useQuery({
127	    queryKey: ['tv-metas', 'mensais', mensalAno, mensalMes],
128	    queryFn: () => fetchMetasMensais(mensalAno, mensalMes),
129	  });
130	
131	  const [redeValue, setRedeValue] = useState('');
132	  const [lojaMensalValues, setLojaMensalValues] = useState<Record<number, string>>({});
133	  // Re-inicializa quando o mês selecionado (re)carrega do banco
134	  useEffect(() => {
135	    const rows = mensaisQuery.data;
136	    if (!rows) return;
137	    const rede = rows.find((r) => r.loja_id === null);
138	    setRedeValue(rede && rede.valor_meta > 0 ? String(rede.valor_meta) : '');
139	    const next: Record<number, string> = {};
140	    for (const row of rows) {
141	      if (row.loja_id != null && row.valor_meta > 0) {
142	        next[row.loja_id] = String(row.valor_meta);
143	      }
144	    }
145	    setLojaMensalValues(next);
146	  }, [mensaisQuery.data]);
147	
148	  const saveMensalMutation = useMutation({
149	    mutationFn: async () => {
150	      const rows = mensaisQuery.data ?? [];
151	      // Linha da REDE (loja_id NULL): o upsert do PostgREST NÃO casa NULL
152	      // no onConflict — select prévio (já no cache da query) + update por
153	      // id quando existe; insert caso contrário.
154	      const redeRow = rows.find((r) => r.loja_id === null) ?? null;
155	      const redeParsed = parseMetaInput(redeValue);
156	      if (redeParsed != null) {
157	        if (redeRow) {
158	          const { error } = await supabase
159	            .from('metas_mensais')
160	            .update({ valor_meta: redeParsed })
161	            .eq('id', redeRow.id);
162	          if (error) throw error;
163	        } else {
164	          const { error } = await supabase.from('metas_mensais').insert({
165	            loja_id: null,
166	            ano: mensalAno,
167	            mes: mensalMes,
168	            valor_meta: redeParsed,
169	          });
170	          if (error) throw error;
171	        }
172	      } else if (redeRow && redeValue.trim() === '') {
173	        // Campo esvaziado que TINHA meta → 0 (semanticamente sem meta)
174	        const { error } = await supabase
175	          .from('metas_mensais')
176	          .update({ valor_meta: 0 })
177	          .eq('id', redeRow.id);
178	        if (error) throw error;
179	      }
180	
181	      // Por loja: loja_id não-nulo casa normal no onConflict
182	      const persistedLojaIds = new Set(
183	        rows
184	          .filter((r) => r.loja_id != null && r.valor_meta > 0)
185	          .map((r) => r.loja_id as number),
186	      );
187	      const lojaRows: Array<{
188	        loja_id: number;
189	        ano: number;
190	        mes: number;
191	        valor_meta: number;
192	      }> = [];
193	      for (const loja of lojasQuery.data ?? []) {
194	        const raw = lojaMensalValues[loja.id] ?? '';
195	        const parsed = parseMetaInput(raw);
196	        if (parsed != null) {
197	          lojaRows.push({
198	            loja_id: loja.id,
199	            ano: mensalAno,
200	            mes: mensalMes,
201	            valor_meta: parsed,
202	          });
203	        } else if (raw.trim() === '' && persistedLojaIds.has(loja.id)) {
204	          lojaRows.push({
205	            loja_id: loja.id,
206	            ano: mensalAno,
207	            mes: mensalMes,
208	            valor_meta: 0,
209	          });
210	        }
211	      }
212	      if (lojaRows.length > 0) {
213	        const { error } = await supabase
214	          .from('metas_mensais')
215	          .upsert(lojaRows, { onConflict: 'loja_id,ano,mes' });
216	        if (error) throw error;
217	      }
218	    },
219	    onSuccess: () => {
220	      toast.success('Meta mensal salva');
221	      queryClient.invalidateQueries({ queryKey: ['tv-metas', 'mensais'] });
222	      queryClient.invalidateQueries({ queryKey: tvDashboardKeys.metasMensais() });
223	    },
224	    onError: (error: Error) => {
225	      toast.error('Erro ao salvar meta mensal', {
226	        description: error.message || 'Tente novamente em instantes.',
227	      });
228	    },
229	  });
230	
231	  // Anos selecionáveis (anterior, corrente, próximo)
232	  const anoOptions = useMemo(() => {
233	    const current = new Date().getFullYear();
234	    return [current - 1, current, current + 1];
235	  }, []);
236	
237	  // Valores dos inputs (string p/ digitação livre), keyed `lojaId:dia`.
238	  // null = ainda não inicializado a partir do banco (NUNCA derivar upserts
239	  // de zeramento antes da inicialização — risco de apagar metas).
240	  const [values, setValues] = useState<Record<string, string> | null>(null);
241	  const initialized = useRef(false);
242	  useEffect(() => {
243	    if (initialized.current || !metasQuery.data) return;
244	    initialized.current = true;
245	    const next: Record<string, string> = {};
246	    for (const meta of metasQuery.data) {
247	      next[cellKey(meta.loja_id, meta.dia_semana)] =
248	        meta.valor_meta > 0 ? String(meta.valor_meta) : '';
