250	    setValues(next);
251	  }, [metasQuery.data]);
252	
253	  const saveMutation = useMutation({
254	    mutationFn: async (rows: MetaRow[]) => {
255	      const { error } = await supabase
256	        .from('metas_vendas')
257	        .upsert(rows, { onConflict: 'loja_id,dia_semana' });
258	      if (error) throw error;
259	    },
260	    onSuccess: () => {
261	      toast.success('Metas salvas com sucesso');
262	      queryClient.invalidateQueries({ queryKey: ['tv-metas', 'valores'] });
263	      queryClient.invalidateQueries({ queryKey: tvDashboardKeys.metas() });
264	    },
265	    onError: (error: Error) => {
266	      toast.error('Erro ao salvar metas', {
267	        description: error.message || 'Tente novamente em instantes.',
268	      });
269	    },
270	  });
271	
272	  // Células que TÊM meta (>0) no banco — pra detectar célula esvaziada
273	  const persistedKeys = useMemo(() => {
274	    const keys = new Set<string>();
275	    for (const meta of metasQuery.data ?? []) {
276	      if (meta.valor_meta > 0) keys.add(cellKey(meta.loja_id, meta.dia_semana));
277	    }
278	    return keys;
279	  }, [metasQuery.data]);
280	
281	  const rows = useMemo(() => {
282	    if (values == null) return [];
283	    const out: MetaRow[] = [];
284	    for (const loja of lojasQuery.data ?? []) {
