291	          // Células que sempre estiveram vazias NÃO são enviadas.
292	          if (persistedKeys.has(key)) {
293	            out.push({ loja_id: loja.id, dia_semana: dia, valor_meta: 0 });
294	          }
295	          continue;
296	        }
297	        const parsed = Number(raw.replace(',', '.'));
298	        if (!Number.isFinite(parsed) || parsed < 0) continue;
299	        out.push({ loja_id: loja.id, dia_semana: dia, valor_meta: parsed });
300	      }
301	    }
302	    return out;
303	  }, [lojasQuery.data, values, persistedKeys]);
304	
305	  const isLoading = lojasQuery.isLoading || metasQuery.isLoading;
306	
307	  return (
308	    <div className="space-y-6 p-4 md:p-6" data-testid="tv-metas-page">
309	      <div className="flex flex-wrap items-center justify-between gap-3">
310	        <div className="flex items-center gap-3">
311	          <Button
312	            variant="ghost"
313	            size="icon"
314	            onClick={() => navigate('/tv')}
315	            data-mia-action="voltar-painel-tv"
