323	          </div>
324	          <div>
325	            <h1 className="font-serif text-2xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF]">
326	              Metas do Painel TV
327	            </h1>
328	            <p className="text-xs font-medium uppercase tracking-widest text-muted-foreground">
329	              Meta diária de vendas por loja e dia
330	            </p>
331	          </div>
332	        </div>
333	        <Button
334	          onClick={() => saveMutation.mutate(rows)}
335	          disabled={saveMutation.isPending || isLoading || rows.length === 0}
336	          data-mia-action="salvar-metas-painel-tv"
337	          className="bg-[#57715B] text-white shadow-lg shadow-[#57715B]/20 hover:bg-[#465b49]"
338	        >
339	          <Save className="mr-2 h-4 w-4" />
340	          {saveMutation.isPending ? 'Salvando…' : 'Salvar metas'}
341	        </Button>
342	      </div>
343	
344	      {/* ── Meta mensal (rede + por loja) — alimenta a strip do mês no /tv ── */}
345	      <GlassCard variant="premium" className="p-6" data-testid="tv-metas-mensal">
