360	            data-mia-action="salvar-meta-mensal-painel-tv"
361	            className="bg-[#57715B] text-white shadow-lg shadow-[#57715B]/20 hover:bg-[#465b49]"
362	          >
363	            <Save className="mr-2 h-4 w-4" />
364	            {saveMensalMutation.isPending ? 'Salvando…' : 'Salvar meta mensal'}
365	          </Button>
366	        </div>
367	
368	        <div className="flex flex-wrap items-end gap-3">
369	          <label className="flex flex-col gap-1 text-xs font-semibold uppercase tracking-wider text-[#57715B] dark:text-[#8FAE94]">
370	            Mês
371	            <select
372	              value={mensalMes}
