388	              onChange={(e) => setMensalAno(Number(e.target.value))}
389	              aria-label="Ano da meta"
390	              className="h-10 rounded-xl border border-[#57715B]/15 bg-white/70 px-3 text-sm font-normal normal-case tracking-normal text-[#2D362E] tabular-nums focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 dark:bg-black/20 dark:text-[#E6DCCF]"
391	            >
392	              {anoOptions.map((ano) => (
393	                <option key={ano} value={ano}>
394	                  {ano}
395	                </option>
396	              ))}
397	            </select>
398	          </label>
399	          <label className="flex flex-col gap-1 text-xs font-semibold uppercase tracking-wider text-[#57715B] dark:text-[#8FAE94]">
400	            Meta da rede
401	            <Input
402	              type="number"
403	              min={0}
404	              step={1000}
405	              inputMode="decimal"
406	              placeholder="R$"
407	              value={redeValue}
408	              onChange={(e) => setRedeValue(e.target.value)}
409	              aria-label="Meta mensal da rede"
410	              data-mia-field="meta-mensal-rede"
411	              className="w-40 rounded-xl border-[#57715B]/15 bg-white/70 text-right tabular-nums focus-visible:ring-[#57715B]/30 dark:bg-black/20"
412	            />
413	          </label>
414	        </div>
415	
416	        {/* Por loja — secundário/colapsável (fallback quando não há meta rede) */}
417	        <button
